<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQuasar} from 'quasar'
import {Boxes,Plus,Search,X,ArrowUpRight,Trash2,Pencil,Globe,Clock,ShieldCheck} from 'lucide-vue-next'
import {useMonitor} from '../stores/monitor'
import {api} from '../services/api'
import {relative,date} from '../services/format'
import type {Application,Check} from '../types'
import StatusBadge from '../components/StatusBadge.vue'
import HistoryChart from '../components/HistoryChart.vue'
const store=useMonitor(),route=useRoute(),router=useRouter(),$q=useQuasar()
const search=ref(''),filter=ref('All states'),selected=ref<Application|null>(null),checks=ref<Check[]>([]),uptime=ref<number|null>(null),editing=ref(false),editingId=ref<number|null>(null),saving=ref(false),error=ref('')
const form=ref({name:'',server:0,url:'',environment:'Production',expected_status:200,interval:30,timeout:5,latency_threshold:2000,assertion_key:'',assertion_value:'',enabled:true})
const manageable=computed(()=>store.data?.servers.filter(s=>s.role==='admin')||[])
const applications=computed(()=>store.data?.applications.filter(a=>`${a.name} ${a.url}`.toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All states'||a.effective_state===filter.value))||[])
const canEdit=computed(()=>!!selected.value&&manageable.value.some(s=>s.id===selected.value?.server))
async function loadChecks(){if(!selected.value)return;error.value='';try{const r=await api(`/applications/${selected.value.id}/checks`);checks.value=r.results;uptime.value=r.uptime_24h}catch(e){error.value=(e as Error).message}}
watch([()=>route.query.app,()=>store.data],()=>{const a=store.data?.applications.find(a=>a.id===Number(route.query.app));selected.value=a||null;if(a)void loadChecks()},{immediate:true})
function close(){selected.value=null;void router.replace('/applications')}
function edit(a?:Application){error.value='';editingId.value=a?.id||null;form.value={name:a?.name||'',server:a?.server||manageable.value[0]?.id||0,url:a?.url||'',environment:a?.environment||'Production',expected_status:a?.expected_status||200,interval:a?.interval||30,timeout:a?.timeout||5,latency_threshold:a?.latency_threshold||2000,assertion_key:a?.assertion_key||'',assertion_value:a?.assertion_value==null?'':JSON.stringify(a.assertion_value),enabled:true};editing.value=true}
async function save(){error.value='';saving.value=true;try{const body={...form.value,assertion_value:form.value.assertion_key?JSON.parse(form.value.assertion_value):null};await api(editingId.value?`/applications/${editingId.value}`:'/applications',{method:editingId.value?'PATCH':'POST',body:JSON.stringify(body)});await store.refresh();editing.value=false;$q.notify({message:'Application check saved',color:'positive'})}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function retire(){if(!selected.value)return;const a=selected.value;$q.dialog({title:'Retire application?',message:`Stop monitoring ${a.name}?`,cancel:true}).onOk(async()=>{try{await api(`/applications/${a.id}`,{method:'DELETE'});close();await store.refresh()}catch(e){error.value=(e as Error).message}})}
</script>
<template><div class="page-header"><div><h1>Applications</h1><p class="subtitle">Healthy hosts are only part of the story.</p></div><q-btn v-if="manageable.length" color="primary" unelevated no-caps @click="edit()"><Plus :size="18"/>Add application</q-btn></div><div class="list-toolbar"><label class="search-box large"><Search :size="17"/><input v-model="search" placeholder="Search applications…" aria-label="Search applications"/></label><q-select v-model="filter" outlined dense :options="['All states','Healthy','Degraded','Down','Pending','Unknown','Maintenance']" class="filter-select"/></div><section class="panel"><header class="panel-header"><h2>Application checks <span class="muted">{{applications.length}}</span></h2><span class="muted">Checked from the monitoring worker</span></header><button v-for="a in applications" :key="a.id" class="app-list-row" @click="router.push(`/applications?app=${a.id}`)"><div class="app-icon"><Boxes :size="24"/></div><div class="identity"><div><strong>{{a.name}}</strong><small>{{a.server_name}} · {{a.environment}}</small><small class="app-url">{{a.url}}</small></div></div><StatusBadge :status="a.effective_state"/><div class="app-response"><b>{{a.latency_ms!==null?Math.round(a.latency_ms)+' ms':'—'}}</b><small>{{relative(a.last_checked)}}</small></div><ArrowUpRight :size="18"/></button><div v-if="!applications.length" class="empty"><Boxes :size="32"/><b>No applications found</b><span>Add an HTTP health check to monitor an application.</span></div></section>
<q-dialog :model-value="!!selected" position="right" full-height @update:model-value="v=>{if(!v)close()}"><q-card v-if="selected" class="detail-panel"><header class="detail-header"><div class="detail-icon"><Boxes :size="24"/></div><div><h2>{{selected.name}}</h2><p>{{selected.server_name}}</p></div><q-btn flat round aria-label="Close application details" @click="close"><X :size="20"/></q-btn></header><div class="detail-body"><StatusBadge :status="selected.effective_state"/><p class="break-word muted">{{selected.url}}</p><div v-if="selected.last_error" class="error-box">{{selected.last_error}}</div><div class="app-detail-stats"><div><Clock :size="20"/><b>{{selected.latency_ms!==null?Math.round(selected.latency_ms)+' ms':'—'}}</b><span>Last response</span></div><div><Globe :size="20"/><b>{{uptime!==null?uptime.toFixed(2)+'%':'—'}}</b><span>Successful checks · 24h</span></div></div><h3>Response time</h3><HistoryChart :points="[...checks].reverse().map(c=>({time:c.checked_at,latency_ms:c.latency_ms}))" mode="latency"/><div class="detail-line"><span>Expected HTTP status</span><b>{{selected.expected_status}}</b></div><div class="detail-line"><span>Check interval / timeout</span><b>{{selected.interval}}s / {{selected.timeout}}s</b></div><div class="detail-line"><span>Slow response threshold</span><b>{{selected.latency_threshold}} ms</b></div><div class="detail-line"><span>TLS certificate expires</span><b>{{date(selected.tls_expires)}}</b></div><h3>Latest checks</h3><div v-for="c in checks.slice(0,12)" :key="c.id" class="check-row"><span class="status-dot" :class="c.success?'good':'bad'"/><span>{{c.success?'Successful check':c.error}}</span><b>{{c.latency_ms!==null?Math.round(c.latency_ms)+' ms':'—'}}</b><small>{{relative(c.checked_at)}}</small></div><p v-if="!checks.length" class="muted">No checks recorded yet.</p><div v-if="error" class="error-box">{{error}}</div><div v-if="canEdit" class="detail-actions"><q-btn flat no-caps @click="edit(selected)"><Pencil :size="16"/>Edit check</q-btn><q-btn flat no-caps color="negative" @click="retire"><Trash2 :size="16"/>Retire</q-btn></div></div></q-card></q-dialog>
<q-dialog v-model="editing"><q-card class="form-dialog"><form @submit.prevent="save"><q-card-section><h2>{{editingId?'Edit application':'Add application'}}</h2><p class="muted">Check the endpoint that proves your application is ready.</p></q-card-section><q-card-section class="form-fields"><q-input v-model="form.name" label="Application name" outlined required/><q-select v-model="form.server" :options="manageable.map(s=>({label:s.name,value:s.id}))" emit-value map-options outlined label="Server"/><q-input v-model="form.url" outlined label="Health-check URL" type="url" required/><q-select v-model="form.environment" :options="['Production','Staging','Development']" outlined label="Environment"/><div class="form-two"><q-input v-model.number="form.expected_status" type="number" outlined label="Expected HTTP status" min="100" max="599"/><q-input v-model.number="form.latency_threshold" type="number" outlined label="Slow threshold (ms)" min="1" max="60000"/></div><div class="form-two"><q-input v-model.number="form.interval" type="number" outlined label="Interval (seconds)" min="30" max="3600"/><q-input v-model.number="form.timeout" type="number" outlined label="Timeout (seconds)" min="1" max="10"/></div><q-input v-model="form.assertion_key" outlined label="JSON assertion key (optional)" hint="Dot path, for example database.status"/><q-input v-if="form.assertion_key" v-model="form.assertion_value" outlined label="Expected JSON value" hint='Valid JSON, for example "healthy" or true'/><div v-if="error" class="error-box" role="alert">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn type="submit" color="primary" unelevated no-caps label="Save application" :loading="saving"/></q-card-actions></form></q-card></q-dialog>
</template>
